def count_points_in_circle(points, center, radius):
    cx, cy = center
    if radius == 0:
        return sum(1 for x, y in points if x == cx and y == cy)
    if radius == 1:
        return sum(1 for x, y in points if (x - cx)**2 + (y - cy)**2 <= 1)
    return sum(1 for x, y in points if (x - cx)**2 + (y - cy)**2 <= radius**2)
```

