    num_rows = len(grid)
    num_cols = len(grid[0])
    for col in range(num_cols):
        is_palindrome = True
        for row in range(num_rows // 2):
            if grid[row][col] != grid[num_rows - 1 - row][col]:
                is_palindrome = False
                break
        if is_palindrome:
            count += 1
    return count
